  show("Join","df1.join(df2, on='id', how='left')");
  show("Rows after",DATA.n);
}else if(m==="io"){
  show("Formats","CSV, Parquet, JSON, IPC, NDJSON");
  show("Fastest","Parquet - columnar");
}else if(m==="stream"){
  show("Streaming",".collect(streaming=True)");
  show("Handles","larger-than-RAM datasets");
}else if(m==="threads"){
  show("Threads","all cores by default");
  show("Note","no GIL games - real parallelism");
}else if(m==="schema"){
  show("Schema","strict dtypes per column");
  show("Catches","type errors at plan time");
}else if(m==="sort"){
  var s=DATA.rows.slice().sort(function(a,b){return b[DATA.col]-a[DATA.col];});
  show("Top row",s[0][DATA.key]+" ("+DATA.col+"="+s[0][DATA.col]+")");
}else if(m==="select"){
  show("select","pick and compute columns in one pass");
  show("Example","df.select(pl.col('a')*2)");
